import os

filepath = '/root/autodl-tmp/freige/freige/training/rsft_generate.py'

with open(filepath) as f:
    content = f.read()

# 1. Add load_progress_from_jsonl function after save_progress
new_func = '''

def load_progress_from_jsonl(output_file, num_generations):
    """从 generations.jsonl 重建已完成的 doc_id 集合（比 progress.json 更可靠）。

    扫描 jsonl 文件，统计每个 doc_id 的条目数。
    完整的 doc（条目数 >= num_generations）标记为已完成。
    不完整的 doc 条目会被从文件中移除，以便重新生成。
    """
    if not Path(output_file).exists():
        return set()
    doc_counts = {}
    with open(output_file) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
                doc_id = rec["doc_id"]
                doc_counts[doc_id] = doc_counts.get(doc_id, 0) + 1
            except (json.JSONDecodeError, KeyError):
                continue
    completed = {did for did, cnt in doc_counts.items() if cnt >= num_generations}
    partial = {did: cnt for did, cnt in doc_counts.items() if cnt < num_generations}
    if partial:
        partial_ids = set(partial.keys())
        logger.warning("Found %d partial docs, truncating from JSONL: %s",
                       len(partial), dict(list(partial.items())[:5]))
        tmp_file = str(output_file) + ".tmp"
        with open(output_file) as fin, open(tmp_file, "w") as fout:
            for line_in in fin:
                try:
                    rec = json.loads(line_in.strip())
                    if rec["doc_id"] not in partial_ids:
                        fout.write(line_in)
                except (json.JSONDecodeError, KeyError):
                    continue
        os.replace(tmp_file, str(output_file))
    total_lines = sum(cnt for did, cnt in doc_counts.items() if did in completed)
    logger.info("Resumed from JSONL: %d complete docs (%d lines)", len(completed), total_lines)
    return completed

'''

marker = '\n\n@torch.no_grad()'
if marker in content:
    content = content.replace(marker, new_func + '\n@torch.no_grad()', 1)
    print("OK: inserted load_progress_from_jsonl")
else:
    print("ERROR: could not find @torch.no_grad() marker")
    exit(1)

# 2. Add --resume argument before --num_shards
resume_arg = '    parser.add_argument("--resume", action="store_true",\n                        help="Resume from existing generations.jsonl instead of progress.json")\n'
if '--resume' not in content:
    target = '    parser.add_argument("--num_shards"'
    if target in content:
        content = content.replace(target, resume_arg + target)
        print("OK: added --resume argument")
    else:
        target2 = '    parser.add_argument("--repetition_penalty"'
        if target2 in content:
            content = content.replace(target2, resume_arg + target2)
            print("OK: added --resume argument (before repetition_penalty)")
        else:
            print("ERROR: could not find insertion point for --resume")
            exit(1)
else:
    print("SKIP: --resume already exists")

# 3. Modify progress loading
old_progress = '    completed = load_progress(output_dir)'
new_progress = '    if args.resume:\n        completed = load_progress_from_jsonl(output_file, args.num_generations)\n    else:\n        completed = load_progress(output_dir)'
if old_progress in content:
    content = content.replace(old_progress, new_progress)
    print("OK: modified progress loading logic")
else:
    print("ERROR: could not find progress loading line")
    exit(1)

with open(filepath, 'w') as f:
    f.write(content)

print("DONE: patch applied successfully")

